{
    "name": "ramprakash.v/php_kit",
    "type": "project",
    "require": {
        "juspay/expresscheckout-php-sdk": "2.0.4"
    },
    "autoload": {
        "psr-4": {
            "RamprakashV\\PhpKit\\": "src/"
        }
    },
    "config": {
        "process-timeout":0
    },
    "scripts": {
        "run_server": "composer install --no-dev && php -S 0.0.0.0:5000 router.php",
        "run_app": "composer install && php Program.php"
    },
    "authors": [
        {
            "name": "Ramprakash Vel"
        }
    ]
}
